  void commit(){requireCurrent();require(parameter_.has_value()&&!fields_,"Choose a parameter and set or discard pending point fields");const auto token=generation_;pending_=true;layout();try{request_("automation.replaceLane",{{"expectedRevision",captured_.revision},{"slot",slot_},{"id",*parameter_},{"points",points_}});pending_=false;require(context_().document==captured_.document&&token==generation_,"Source changed during Apply / newer draft retained");load(false);status(L"Song automation saved / plugin Undo restores the previous lane");}catch(...){pending_=false;layout();throw;}layout();}
