    place(indexLabel,258,h-169,138,18);place(pointIndex,258,h-150,88,26);place(selectPoint,354,h-150,84,26);place(previous,446,h-150,40,26);place(next,494,h-150,40,26);place(unitsLabel,552,h-169,140,18);place(units,552,h-150,160,180);
    place(timeLabel,258,h-113,170,18);place(time,258,h-94,170,26);place(valueLabel,436,h-113,178,18);place(value,436,h-94,178,26);place(setPoint,622,h-94,106,26);place(addPoint,736,h-94,106,26);place(deletePoint,850,h-94,134,26);
    x=18;for(auto [id,width]:std::initializer_list<std::pair<int,int>>{{apply,104},{reload,104},{undo,88},{redo,88},{clear,112}}){place(id,x,h-51,width,28);x+=width+8;}place(close,w-118,h-51,100,28);place(statusLabel,18,h-22,w-36,20);
