  void paint(RenderSurface &s)override{const auto [w,h]=size();s.fill(0,0,w,h,0x18222d);const auto r=canvas_.viewport;s.fill(r.x,r.y,r.w,r.h,0x101923);s.clip(r.x,r.y,r.w,r.h);for(int i=0;i<=4;++i){const auto y=r.y+i*r.h/4;s.line(r.x,y,r.x+r.w,y,0x2a3947);}const auto step=std::pow(10.,std::floor(std::log10(std::max(1./48000,(canvas_.end-canvas_.start)/256/8))));for(double t=std::ceil(canvas_.start/256/step)*step;t<=canvas_.end/256;t+=step){const auto x=canvas_.screen(t*256,0).x;s.line(x,r.y,x,r.y+r.h,0x2a3947);}for(const auto &line:lines_)s.line(line.a.x,line.a.y,line.b.x,line.b.y,0x6edac5,2);for(size_t i=0;i<canvas_.handles.size();++i){const auto p=canvas_.handles[i];s.fill(p.x-3,p.y-3,6,6,int(handles_[i])==selected_?0xffd08a:0x6edac5);}s.unclip();s.outline(r.x,r.y,r.w,r.h,GetFocus()==window_?0x6edac5:0x334757);wchar_t text[160]{};swprintf_s(text,L"Seconds %.4f–%.4f · native values %.4f–%.4f",canvas_.start/256,canvas_.end/256,minimum()+canvas_.valueLow*(maximum()-minimum()),minimum()+canvas_.valueHigh*(maximum()-minimum()));s.uiText(text,r.x,r.y-22,r.w,0x93aabd);}
